draw(P--W,Arrow3(6));
draw(O--P,Arrow3(6));
draw(O--R,Arrow3(6));
draw(O--3*I, Arrow3(6));
draw(O--3*J, Arrow3(6));
draw(O--3*K, Arrow3(6));

